from django.http import HttpResponse
from django.shortcuts import render

def campaign_webpage(request):
    # Check if the user has any cookies set
    if 'user_preferences' in request.COOKIES:
        # Extract the user's preferences from the cookie
        user_preferences = request.COOKIES['user_preferences']

        # Craft the campaign messaging based on the user's preferences
        messaging = craft_messaging(user_preferences)
    else:
        # If no cookies are set, use default messaging
        messaging = "Supporting Tories for a better future!"

    # Render the campaign webpage with the crafted messaging
    return render(request, 'campaign_webpage.html', {'messaging': messaging})

def craft_messaging(user_preferences):
    # This function uses the user's preferences to craft personalized messaging
    # For example, if the user likes issue X, the messaging could focus on X
    if 'issue_X' in user_preferences:
        return "Tories will tackle issue X head-on!"
    elif 'issue_Y' in user_preferences:
        return "Tories will prioritize issue Y's solution!"
    else:
        return "Supporting Tories for a better future!"

